def acervo_titles():
    """normaliza nomes de arquivos do acervo para comparar com candidatos"""
    s = set()
    for f in BIB.rglob("*.md"):
        if "_incoming" in f.parts or "_extracted" in f.parts:
            continue
        s.add(re.sub(r"[^a-z0-9]", "", f.stem.lower()))
        # tambem cada palavra relevante
        for w in re.findall(r"[A-Za-z]{5,}", f.stem):
            s.add(w.lower())
    return s


def acervo_por_titulo():
    """Indice (titulo normalizado) -> caminho, lido do FRONTMATTER do acervo.

    Bug 2026-10-26: o dedup comparava so o NOME DO ARQUIVO. O acervo canonico
    usa o slug do arquivo, mas o titulo real esta no frontmatter — e os dois
    divergem. Resultado: a rodada rebaixou 10 livros que JA estavam no acervo
    (todos os 10 duplicados byte-a-byte de 2026-10-25).

    Este indice le o `titulo:` do frontmatter (fonte de verdade do livro) e
    tambem o nome do arquivo, para casar os dois sentidos.
    """
    idx = {}
    for f in BIB.rglob("*.md"):
        if "_incoming" in f.parts or "_extracted" in f.parts:
            continue
        try:
            txt = f.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        chaves = {re.sub(r"[^a-z0-9]", "", f.stem.lower())}
        m = re.search(r'^titulo:\s*["\']?(.*?)["\']?\s*$', txt[:2000], re.M)
        if m:
            t = re.sub(r"[^a-z0-9]", "", m.group(1).lower())
            if len(t) >= 8:
                chaves.add(t)
        for c in chaves:
            if len(c) >= 8:
                idx.setdefault(c, str(f))
    return idx


def ja_no_acervo(titulo, autor, idx_titulos):
    """True se o livro (titulo+autor) ja esta no acervo. Devolve (bool, caminho)."""
    tnorm = re.sub(r"[^a-z0-9]", "", (titulo or "").lower())
    anorm = re.sub(r"[^a-z0-9]", "", (autor or "").lower())
    if len(tnorm) < 8:
        return False, None
    # 1) titulo exato (normalizado) — caso mais comum
    if tnorm in idx_titulos:
        return True, idx_titulos[tnorm]
    # 2) prefixo forte: um titulo do acervo COMECA com o titulo candidato
    #    (ex.: candidato "Basics of Biblical Greek" vs acervo
    #     "Basics of Biblical Greek Grammar: Fourth Edition")
    for k, path in idx_titulos.items():
        if len(k) >= 12 and (k.startswith(tnorm) or tnorm.startswith(k)):
            return True, path
    # 3) autor strongly indica obra identica + titulo muito similar
    if anorm:
        for k, path in idx_titulos.items():
            if len(k) < 12:
                continue
            if k.startswith(tnorm[:max(10, len(tnorm) - 6)]) or tnorm.startswith(k[:max(10, len(k) - 6)]):
                return True, path
    return False, None


def _corpo_sem_frontmatter(path):
    """Le o arquivo e devolve o CORPO (sem o bloco de frontmatter)."""
    try:
        txt = Path(path).read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return None
    m = re.match(r"^---\s*\n(.*?)\n---\s*\n?", txt, re.S)
    if m:
        return txt[m.end():]
    return txt


def achar_duplicado_por_conteudo(novo_path):
    """Devolve o caminho de um .md do acervo com o MESMO CORPO, ou None.

    Guarda forte contra re-download da mesma obra. Compara o corpo sem o
    frontmatter (o frontmatter muda entre rodadas: tags, ano, gap_origem).
    """
    corpo = _corpo_sem_frontmatter(novo_path)
    if not corpo or len(corpo) < 500:
        return None
    # assinatura: sha1 dos primeiros 200 KB (o comeco do livro identifica a obra)
    import hashlib
    sig = hashlib.sha1(corpo[:200000].encode("utf-8", "ignore")).hexdigest()
    # compara por caminho RESOLVIDO — o arquivo novo pode ser passado relativo
    try:
        alvo = str(Path(novo_path).resolve())
    except Exception:
        alvo = str(novo_path)
    for f in BIB.rglob("*.md"):
        if "_incoming" in f.parts or "_extracted" in f.parts:
            continue
        try:
            if str(f.resolve()) == alvo:
                continue
        except Exception:
            if str(f) == str(novo_path):
                continue
        c = _corpo_sem_frontmatter(f)
        if not c or len(c) < 500:
            continue
        if hashlib.sha1(c[:200000].encode("utf-8", "ignore")).hexdigest() == sig:
            return str(f)
    return None


