#!/usr/bin/env python3
"""
RECONSTRUTOR FINAL das KBs — normaliza caminho_md em TODA a estrutura do YAML.

Trata:
  - root do KB pode ser dict OU string (formato "- KB — Nome")
  - sub-listas em qualquer nivel (materiais, constituicao_estatutos, etc.)
  - dedup por caminho_md dentro do KB
  - caminho partido em 2 linhas (bug do safe_dump antigo)
  - prefixo legado (biblioteca/, data/ sem ./)
"""
import re
import sys
import unicodedata
from collections import defaultdict
from pathlib import Path

import yaml
sys.path.insert(0, str(Path(__file__).parent))
import identidade

ROOT = Path("/home/study-agent").resolve()
BIB = (ROOT / "data/biblioteca").resolve()
GLOBAL = BIB / "global"
STOP = {"de", "da", "do", "the", "a", "o", "and", "e", "of", "para", "com"}


def norm(s):
    s = unicodedata.normalize("NFKD", str(s))
    s = "".join(c for c in s if not unicodedata.combining(c))
    s = s.lower().replace("\xa0", " ")
    s = re.sub(r"\.(md|yaml)$", "", s, flags=re.I)
    s = re.sub(r"[^a-z0-9 ]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def kw(s, n=10):
    return [w for w in norm(s).split() if len(w) > 3 and w not in STOP][:n]


def index_disco():
    arq = []
    pp = defaultdict(list)
    for f in BIB.rglob("*.md"):
        rel = str(f.relative_to(BIB))
        if rel.startswith("_"):
            continue
        b = f.stem
        arq.append((str(f), b))
        for w in set(kw(b, 4)):
            pp[w].append((str(f), b))
    return arq, pp


def match(titulo, base, arq, pp):
    for f, b in arq:
        if b == base:
            return f
    tk = kw(titulo, 10)
    if not tk:
        return None
    c = defaultdict(int)
    for w in tk:
        for f, b in pp.get(w, []):
            c[f] += 1
    if c:
        m, s = max(c.items(), key=lambda x: x[1])
        if s >= max(2, len(tk) - 1):
            return m
    for f, b in arq:
        bw = set(kw(b, 14))
        if all(w in bw for w in tk):
            return f
    return None


def canon(hit):
    hp = Path(hit).resolve()
    try:
        return "./data/biblioteca/" + str(hp.relative_to(BIB))
    except ValueError:
        try:
            return "./data/" + str(hp.relative_to((ROOT / "data").resolve()))
        except ValueError:
            return "./" + str(hp.relative_to(ROOT))


def processar_kb(kbpath, arq, pp, stats):
    txt = kbpath.read_text(encoding="utf-8")
    try:
        d = yaml.safe_load(txt)
    except Exception as e:
        stats["yaml_err"].append((kbpath.name, str(e)[:60]))
        return
    if not isinstance(d, dict):
        return

    seen = set()

    def processar_lista(lst):
        out = []
        for m in lst:
            if not isinstance(m, dict):
                continue
            mm = dict(m)
            c = str(mm.get("caminho_md") or "").replace("\xa0", " ").strip()
            if c.startswith("biblioteca/"):
                c = "./data/" + c
            elif c.startswith("data/") and not c.startswith("./data/"):
                c = "./" + c
            base = Path(c).name if c else ""
            if base.endswith(".md"):
                base = base[:-3]
            hit = None
            if c:
                cand = ROOT / c.replace("./", "", 1)
                if cand.exists():
                    hit = str(cand.resolve())
            if not hit and base:
                hit = match(mm.get("titulo", ""), base, arq, pp)
            if not hit:
                stats["drop"] += 1
                continue
            novo = canon(hit)
            if novo in seen:
                stats["dup"] += 1
                continue
            seen.add(novo)
            mm["caminho_md"] = novo
            for k in list(mm.keys()):
                if isinstance(mm[k], str):
                    mm[k] = mm[k].replace("\xa0", " ").strip()
            # higiene: o catalogo fala do CONTEUDO, nao da origem do download
            for k in ("fonte", "origem", "download_em", "gap_origem", "zlib_id",
                      "zlib_hash", "caminho_original", "caminho_md_alt2"):
                if k in mm and isinstance(mm[k], str) and identidade.tem_sujeira(mm[k]):
                    mm.pop(k, None)
            out.append(mm)
            stats["keep"] += 1
        return out

    def walk(o):
        if isinstance(o, dict):
            for k, v in list(o.items()):
                if isinstance(v, list) and v and isinstance(v[0], dict) and \
                        any("caminho_md" in (x or {}) for x in v if isinstance(x, dict)):
                    o[k] = processar_lista(v)
                else:
                    walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)

    walk(d)
    if "tags" in d and isinstance(d["tags"], list):
        pass
    # metadata de atualizacao
    # BUG 2026-10-26: escrevia uma data FIXA ("2026-10-24T15:20"), sobrescrevendo
    # a data real de atualizacao de cada KB — o git diff mostrava regressao
    # (de 2026-10-26 para 2026-10-24) mesmo sem ter mexido no conteudo.
    import datetime
    agora = datetime.datetime.now(datetime.timezone.utc).astimezone()
    stamp = agora.strftime("%Y-%m-%dT%H:%M:%S%z")
    roots = [k for k in d if k != "tags"]
    if roots:
        r = d[roots[0]]
        if isinstance(r, dict):
            r["atualizado_em"] = stamp
            r["atualizado_por"] = "bibliotecario (reconstrutor de KBs)"

    class D(yaml.SafeDumper):
        pass
    D.ignore_aliases = lambda *a: True
    kbpath.write_text(yaml.dump(d, Dumper=D, allow_unicode=True, sort_keys=False,
                                default_flow_style=False, width=4096), encoding="utf-8")


def main():
    arq, pp = index_disco()
    print(f"acervo: {len(arq)} .md")
    stats = {"keep": 0, "drop": 0, "dup": 0, "yaml_err": []}

    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        processar_kb(kbpath, arq, pp, stats)

    print(f"materiais: {stats['keep']} | descartados: {stats['drop']} | "
          f"dup: {stats['dup']} | yaml_err: {len(stats['yaml_err'])}")
    for n, e in stats["yaml_err"]:
        print(f"   [YAML] {n}: {e}")

    # ---- revisao final ----
    bad = []
    tot = 0
    for kbpath in sorted(GLOBAL.glob("kb-*.yaml")):
        try:
            d = yaml.safe_load(kbpath.read_text(encoding="utf-8"))
        except Exception as e:
            bad.append((kbpath.name, f"YAML INVALIDO: {str(e)[:50]}"))
            continue

        def walk2(o):
            if isinstance(o, dict):
                yield o
                for v in o.values():
                    yield from walk2(v)
            elif isinstance(o, list):
                for v in o:
                    yield from walk2(v)

        titles = []
        for o in walk2(d):
            if isinstance(o, dict) and "caminho_md" in o:
                c = o["caminho_md"]
                if isinstance(c, str) and c:
                    tot += 1
                    if not (ROOT / c.replace("./", "", 1)).exists():
                        bad.append((kbpath.name, "PATH: " + c[:60]))
                    if o.get("titulo"):
                        titles.append(c.strip().lower())
        for t in set(titles):
            if titles.count(t) > 1:
                bad.append((kbpath.name, "DUP: " + t[:55]))

    print(f"\nMATERIAIS COM PATH: {tot} | PROBLEMAS: {len(bad)}")
    for kb, c in bad[:15]:
        print(f"   {kb:<36} {c}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

